/* **************************************************************************** */
/* LM1,LM2           =>   MULTIPLICITY OF HITS ON W1,W2 */
/* LM_1,LM_2   =>   MULTIPLICITY OF HITS WITH GOOD TOF AND ADC ON W1,W2 */

/* M_WAL             =>   # OF TRACKS WITH ASSOCIATION W1-W2 OR ONLY W1 */
/* **************************************************************************** */
/* DESCRIPTION OF HITS AFTER TRACK RECONSTRUCTION */
/* ************************************************ */
/* I=1,LM1_COR */
/* IASS_W1(I)   =   0 =>   THE I-TH HIT ON W1 IS NOT  ASSOCIATED TO A HIT ON W2 */

/*              =   2 =>   THE I-TH HIT ON W1 IS WELL ASSOCIATED TO A HIT ON W2 */

/*              =  -1 =>   THE I-TH HIT ON W1 IS REABSORBED TO A CONTIGOUS HIT */
/*                         ON W1 ASSOCIATED TO W2 */

/*              = -11 =>   THE I-TH HIT ON W1 IS REABSORBED TO A CONTIGOUS HIT */
/*                         ON W1 NOT ASSOCIATED TO W2 */

/*              =  -2 =>   THE I-TH HIT ON W1 IS ASSOCIATED TO A DOUBLE HIT */
/*                         ON SAME BAR ON W2 */

/*              =  -3 =>   THE I-TH HIT ON W1 IS A DOUBLE HIT */
/*                         ON THE SAME BAR ON W1 */

/* I=1,LM2_COR */
/* IASS_W2(I)   =   0 =>   THE I-TH HIT ON W2 IS NOT  ASSOCIATED TO A HIT ON W1 */

/*              =   2 =>   THE I-TH HIT ON W2 IS WELL ASSOCIATED TO A HIT ON W1 */

/*              =  -1 =>   THE I-TH HIT ON W2 IS REABSORBED TO A CONTIGOUS HIT */
/*                         ON W2 ASSOCIATED TO W1 */

/*              = -11 =>   THE I-TH HIT ON W2 IS REABSORBED TO A CONTIGOUS HIT */
/*                         ON W2 NOT ASSOCIATED TO W1 */

/*              =  -2 =>   THE I-TH HIT ON W2 IS ASSOCIATED TO A DOUBLE HIT */
/*                         ON SAME BAR ON W1 */

/*              =  -3 =>   THE I-TH HIT ON W2 IS A DOUBLE HIT ON THE SAME BAR */
/*                         ON W2 */
/* *************************************************************************** */
/* DESCRIPTION OF HIT REABSORPTION ON SINGLE WALL (INTERNAL VARIABLE) */
/* ******************************************************************* */
/* I=1,LM1_COR */
/* IREC_W1(I)   = 0  =>   THE I-TH HIT ON W1 HAS NOT BEEN REABSORBED */

/*              = 1  =>   THE I-TH HIT ON W1 HAS BEEN ATTACHED TO AN */
/*                        ASSOCIATED HIT */

/*              = 2  =>   THE I-TH HIT ON W1 HAS BEEN ATTACHED TO A */
/*                        NOT ASSOCIATED HIT */

/* I=1,LM2_COR */
/* IREC_W2(I)   = 0  =>   THE I-TH HIT ON W2 HAS NOT BEEN REABSORBED */

/*              = 1  =>   THE I-TH HIT ON W2 HAS BEEN ATTACHED TO AN */
/*                        ASSOCIATED HIT */

/*              = 2  =>   THE I-TH HIT ON W2 HAS BEEN ATTACHED TO A */
/*                        NOT ASSOCIATED HIT */
/* *************************************************************************** */
/* DESCRIPTION OF TRACKS */
/* ********************** */
/* I = 1,M_WAL */
/* IASS_TRACK(I)=  0  =>   THE I-TH TRACK HAS A HIT ON W1 AND A HIT ON W2 */

/*              = 10  =>   THE I-TH TRACK HAS A HIT ON W1 */

/*              = -2  =>   the I-TH TRACK HAS A REABSORBED HIT ON W1 AND */
/*                         A HIT ON W2 (TOF AND DE ARE TAKEN FROM W2) */

/*              =  1  =>   THE I-TH TRACK COMES FROM THE RECONSTRUCTION OF A */
/*                         DOUBLE HIT ON THE SAME BAR OF W2 */
/*                         (TOF AND DE ARE TAKEN FROM W1) */
/*                         the splitted hit on w2 was associated to the */
/*                         other hit on w1 */

/*              =  2  =>   THE I-TH TRACK COMES FROM THE RECONSTRUCTION OF A */
/*                         DOUBLE HIT ON THE SAME BAR OF W1 */
/*                         (TOF AND DE ARE TAKEN FROM W2) */
/*                         the splitted hit on w1 was associated to the */
/*                         other hit on w2 */

/*              =  3  =>   THE I-TH TRACK COMES FROM THE RECONSTRUCTION OF A */
/*                         DOUBLE HIT ON THE SAME BAR OF W1 */
/*                         (TOF AND DE ARE TAKEN FROM W2) */
/*                         both hits on w1 were not associated */

/*              =  4  =>   THE I-TH TRACK COMES FROM THE RECONSTRUCTION OF A */
/*                         DOUBLE HIT ON THE SAME BAR OF W2 */
/*                         (TOF AND DE ARE TAKEN FROM W1) */
/*                         both hits on w2 were not associated */
/* *************************************************************************** */
/* TRACK VARIABLES */
/* **************** */
/* WAL_PAR(I,M_WAL) */
/* I = 1             =>   X (FROM W2 IF IASS_TRACK(M_WAL)=0 OR 2, */
/*                           FROM W1 IF IASS_TRACK(M_WAL)=1) */
/* I = 2             =>   Y (FROM W1 IF IASS_TRACK(M_WAL)=0 OR 1, */
/*                           FROM W2 IF IASS_TRACK(M_WAL)=2) */
/* I = 3             =>   TOF W1 (OR W2 FOR DOUBLE HITS ON THE SAME BAR ON W1) */
/* I = 4             =>   DE  W1 (OR W2 FOR DOUBLE HITS ON THE SAME BAR ON W1) */
/* I = 5             =>   TOF W2 (OR W1 FOR DOUBLE HITS ON THE SAME BAR ON W2) */
/*                               (= 0 IF IASS_TRACK(M_WAL)=1) */
/* I = 6             =>   DE  W2 (OR W1 FOR DOUBLE HITS ON THE SAME BAR ON W2) */
/*                               (= 0 IF IASS_TRACK(M_WAL)=1) */
/* I = 7             =>   TOF (FROM W1 OR W2) */
/* I = 8             =>   DE  (FROM W1 OR W2) */
/* **************************************************************************** */
/* TRACK INDEX */
/* ************ */
/* IND_PAR(I,M_WAL) */
/* I = 1             =>   LM1_COR */
/* I = 2             =>   LM2_COR */
/* I = 3             =>   INDEX OF HIT ON W1 */
/* I = 4             =>   INDEX OF HIT ON W2 */
/* ***************************************************************************** */
